sp_widget.client_script:
api.controller = function($window, $timeout) {

    var c = this;


    /* ============================================================
       STATE
       ============================================================ */

    c.loading = true;

    c.profileFound = false;

    c.profile = {};

    c.editProfile = {};

    c.editMode = false;

    c.saving = false;

    c.saveSuccess = false;

    c.saveError = '';

    c.requestedTrainerId = '';


    /* ============================================================
       GET TRAINER ID FROM URL
       ============================================================ */

    c.getCurrentTrainerId = function() {

        var trainerId = '';

        try {

            var params =
                new URLSearchParams(
                    window.location.search
                );

            trainerId =
                params.get('trainer') || '';

        } catch (e) {

            trainerId = '';

        }

        return String(
            trainerId || ''
        ).trim();

    };


    c.currentTrainerId =
        c.getCurrentTrainerId();

    c.requestedTrainerId =
        c.currentTrainerId;


    /* ============================================================
       INITIALIZE
       ============================================================ */

    c.initializeProfile = function() {

        c.loading = false;

        if (
            c.data &&
            c.data.profileFound &&
            c.data.profile
        ) {

            c.profileFound = true;

            c.profile =
                c.data.profile;

            c.editProfile =
                angular.copy(
                    c.profile
                );

        } else {

            c.profileFound = false;

            c.profile = {};

            c.editProfile = {};

        }

    };


    /* ============================================================
       START EDIT
       ============================================================ */

    c.startEdit = function() {

        if (!c.profileFound) {

            return;

        }

        c.saveError = '';

        c.saveSuccess = false;

        c.editProfile =
            angular.copy(
                c.profile
            );

        c.editMode = true;

        $timeout(
            function() {

                var input =
                    document.querySelector(
                        '.c360-edit-section input:not([disabled])'
                    );

                if (input) {

                    try {

                        input.focus();

                    } catch (e) {}

                }

            },
            100
        );

    };


    /* ============================================================
       CANCEL EDIT
       ============================================================ */

    c.cancelEdit = function() {

        c.editProfile =
            angular.copy(
                c.profile
            );

        c.editMode = false;

        c.saving = false;

        c.saveError = '';

    };


    /* ============================================================
       SAVE PROFILE
       ============================================================ */

    c.saveProfile = function() {

        if (c.saving) {

            return;

        }


        c.saveError = '';

        c.saveSuccess = false;


        if (
            !c.editProfile.trainerId
        ) {

            c.saveError =
                'Trainer ID is missing.';

            return;

        }


        if (
            !c.editProfile.trainerName ||
            !String(
                c.editProfile.trainerName
            ).trim()
        ) {

            c.saveError =
                'Trainer Name is required.';

            return;

        }


        if (
            c.editProfile.rating !== '' &&
            c.editProfile.rating !== null &&
            c.editProfile.rating !== undefined
        ) {

            var rating =
                parseFloat(
                    c.editProfile.rating
                );

            if (
                isNaN(rating) ||
                rating < 0 ||
                rating > 5
            ) {

                c.saveError =
                    'Rating must be between 0 and 5.';

                return;

            }

        }


        if (
            c.editProfile.experience !== '' &&
            c.editProfile.experience !== null &&
            c.editProfile.experience !== undefined
        ) {

            var experience =
                parseInt(
                    c.editProfile.experience,
                    10
                );

            if (
                isNaN(experience) ||
                experience < 0
            ) {

                c.saveError =
                    'Experience cannot be negative.';

                return;

            }

        }


        if (
            c.editProfile.totalInterviews !== '' &&
            c.editProfile.totalInterviews !== null &&
            c.editProfile.totalInterviews !== undefined
        ) {

            var interviews =
                parseInt(
                    c.editProfile.totalInterviews,
                    10
                );

            if (
                isNaN(interviews) ||
                interviews < 0
            ) {

                c.saveError =
                    'Total Interviews cannot be negative.';

                return;

            }

        }


        c.saving = true;


        c.data.action =
            'saveProfile';


        c.data.profile =
            angular.copy(
                c.editProfile
            );


        c.server.update().then(

            function(response) {

                c.saving = false;


                if (
                    response &&
                    response.data &&
                    response.data.saveSuccess
                ) {

                    c.profileFound =
                        response.data.profileFound;

                    c.profile =
                        response.data.profile || {};

                    c.editProfile =
                        angular.copy(
                            c.profile
                        );

                    c.editMode = false;

                    c.saveSuccess = true;

                    c.saveError = '';


                    $timeout(
                        function() {

                            c.saveSuccess =
                                false;

                        },
                        3500
                    );

                } else {

                    c.saveError =
                        (
                            response &&
                            response.data &&
                            response.data.saveError
                        ) ||
                        'The trainer profile could not be updated.';

                }

            },

            function() {

                c.saving = false;

                c.saveError =
                    'A server error occurred while saving the trainer profile.';

            }
        );

    };


    /* ============================================================
       REFRESH
       ============================================================ */

    c.refreshProfile = function() {

        c.loading = true;

        c.editMode = false;

        c.saveError = '';

        c.saveSuccess = false;


        c.data.action =
            'loadProfile';


        c.server.update().then(

            function(response) {

                c.loading = false;


                if (
                    response &&
                    response.data
                ) {

                    c.profileFound =
                        response.data.profileFound;

                    c.profile =
                        response.data.profile || {};

                    c.editProfile =
                        angular.copy(
                            c.profile
                        );

                } else {

                    c.profileFound = false;

                }

            },

            function() {

                c.loading = false;

                c.profileFound = false;

                c.saveError =
                    'Unable to refresh the trainer profile.';

            }
        );

    };


    /* ============================================================
       NAVIGATION
       ============================================================ */

    c.openPage = function(pageId) {

        if (!pageId) {

            return;

        }


        var trainerId =
            c.currentTrainerId ||
            c.getCurrentTrainerId();


        var url =
            '?id=' +
            encodeURIComponent(
                pageId
            );


        if (trainerId) {

            url +=
                '&trainer=' +
                encodeURIComponent(
                    trainerId
                );

        }


        $window.location.href =
            url;

    };


    /* ============================================================
       ESCAPE KEY
       ============================================================ */

    c.onKeyDown = function(event) {

        if (
            event &&
            event.keyCode === 27 &&
            c.editMode
        ) {

            c.cancelEdit();

        }

    };


    /* ============================================================
       INITIAL LOAD
       ============================================================ */

    c.initializeProfile();


    /* ============================================================
       CLEANUP
       ============================================================ */

    c.$onDestroy = function() {

        try {

            document.body.style.overflow =
                '';

        } catch (e) {}

    };

};

sp_widget.css:
/* ============================================================
   CAMPUS360 TRAINER PROFILE
   Matched to the Trainer Dashboard visual system
   (same accent, type, card radius/shadow, FA icon language)
   ============================================================ */

.c360-trainer-profile,
.c360-trainer-profile * {
    box-sizing: border-box;
    font-family: Arial, Helvetica, sans-serif;
}

.c360-trainer-profile {
    min-height: 100vh;
    padding: 28px 30px 55px;
    background: #f4f7fb;
    color: #172a33;
    font-size: 15px;
    line-height: 1.45;
}

.c360-page-inner {
    max-width: 1120px;
    margin: 0 auto;
}


/* ============================================================
   TOPBAR  (mirrors .trainer-topbar)
   ============================================================ */

.c360-profile-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 20px;
}

.c360-topbar-eyebrow {
    display: block;
    color: #673cff;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 1.4px;
}

.c360-topbar-title {
    display: block;
    margin-top: 3px;
    color: #172a33;
    font-size: 20px;
    font-weight: 800;
}

.c360-profile-actions {
    display: flex;
    align-items: center;
    gap: 9px;
}

.c360-icon-button {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    border: 1px solid #dfe6ee;
    background: #ffffff;
    color: #536476;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.c360-icon-button:hover {
    color: #673cff;
    border-color: #c9baff;
    background: #f8f5ff;
}

.c360-text-button {
    min-height: 38px;
    padding: 0 14px;
    border-radius: 10px;
    border: 1px solid #dfe6ee;
    background: #ffffff;
    color: #405568;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 7px;
}

.c360-text-button:hover {
    border-color: #c9baff;
    color: #673cff;
    background: #f8f5ff;
}

.c360-solid-button {
    min-height: 38px;
    padding: 0 15px;
    border-radius: 10px;
    border: 1px solid #673cff;
    background: #673cff;
    color: #ffffff;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    box-shadow: 0 4px 10px rgba(103, 60, 255, 0.16);
}

.c360-solid-button:hover {
    background: #5730d8;
    border-color: #5730d8;
}


/* ============================================================
   IDENTITY BANNER  (mirrors .trainer-welcome + .trainer-id-card)
   ============================================================ */

.c360-profile-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 20px;
    padding: 20px 22px;
    background: #ffffff;
    border: 1px solid #dfe6ee;
    border-radius: 15px;
    box-shadow: 0 5px 16px rgba(31, 45, 61, 0.04);
}

.c360-profile-banner-left {
    display: flex;
    align-items: center;
    gap: 15px;
    min-width: 0;
}

.c360-profile-avatar {
    width: 52px;
    height: 52px;
    flex: 0 0 52px;
    border-radius: 12px;
    background: #673cff;
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    font-weight: 800;
}

.c360-profile-heading h1 {
    margin: 0;
    color: #172a33;
    font-size: 22px;
    font-weight: 800;
    line-height: 1.2;
}

.c360-profile-meta {
    margin-top: 4px;
    color: #65758a;
    font-size: 12px;
    font-weight: 700;
}

.c360-meta-separator {
    margin: 0 7px;
    color: #c3cbd8;
}

.c360-id-card {
    flex: 0 0 auto;
    min-width: 130px;
    padding: 11px 15px;
    border-radius: 11px;
    background: #f7f3ff;
    border: 1px solid #dcd2ff;
}

.c360-id-card span {
    display: block;
    color: #77879a;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 1px;
}

.c360-id-card strong {
    display: block;
    margin-top: 4px;
    color: #673cff;
    font-size: 13px;
    font-weight: 900;
}


/* ============================================================
   LOADING / NOT FOUND  (mirrors .trainer-empty language)
   ============================================================ */

.c360-profile-message {
    min-height: 170px;
    margin-bottom: 20px;
    padding: 20px;
    display: flex;
    align-items: center;
    gap: 16px;
    background: #ffffff;
    border: 1px solid #dfe6ee;
    border-radius: 15px;
    box-shadow: 0 5px 16px rgba(31, 45, 61, 0.04);
}

.c360-message-symbol {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    border-radius: 11px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
}

.c360-profile-message .c360-message-symbol {
    background: #eee9ff;
    color: #673cff;
}

.c360-profile-error .c360-message-symbol {
    background: #ffe1e1;
    color: #bd303a;
}

.c360-profile-message h2 {
    margin: 0;
    color: #172a33;
    font-size: 17px;
    font-weight: 800;
}

.c360-profile-message p {
    margin: 5px 0 0;
    color: #65768a;
    font-size: 12px;
}

.c360-profile-message .c360-text-button {
    margin-top: 12px;
}


/* ============================================================
   SECTION PANELS  (mirrors .trainer-panel)
   ============================================================ */

.c360-profile-section {
    margin-bottom: 16px;
    background: #ffffff;
    border: 1px solid #dfe6ee;
    border-radius: 15px;
    box-shadow: 0 5px 16px rgba(31, 45, 61, 0.04);
    overflow: hidden;
}

.c360-section-heading {
    padding: 18px 20px 14px;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 15px;
}

.c360-section-label {
    display: block;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 1.4px;
}

.c360-section-heading h2 {
    margin: 4px 0 0;
    color: #172a33;
    font-size: 17px;
    font-weight: 900;
}

.c360-section-heading p {
    margin: 4px 0 0;
    color: #65768a;
    font-size: 11px;
}

.c360-section-icon {
    width: 34px;
    height: 34px;
    flex: 0 0 34px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
}

/* Section accent families — reuse the dashboard's four accent hues */

.c360-personal-section .c360-section-label { color: #146eb6; }
.c360-personal-section .c360-section-icon { background: #dcedff; color: #146eb6; }

.c360-professional-section .c360-section-label { color: #673cff; }
.c360-professional-section .c360-section-icon { background: #e7ddff; color: #673cff; }

.c360-performance-section .c360-section-label { color: #bd6b0b; }
.c360-performance-section .c360-section-icon { background: #ffe7c7; color: #bd6b0b; }

.c360-account-section .c360-section-label { color: #158057; }
.c360-account-section .c360-section-icon { background: #d9f2e5; color: #158057; }

.c360-expertise-section .c360-section-label { color: #087e71; }
.c360-expertise-section .c360-section-icon { background: #d2f1eb; color: #087e71; }


/* ============================================================
   INFORMATION ROWS (personal / account)
   ============================================================ */

.c360-information-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    padding: 0 20px 16px;
}

.c360-information-field {
    min-height: 60px;
    padding: 12px 14px;
    border-radius: 10px;
    background: #f8fafc;
    border: 1px solid #eaeef3;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.c360-information-field span {
    color: #65768a;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 0.9px;
    margin-bottom: 4px;
}

.c360-information-field strong {
    color: #172a33;
    font-size: 13px;
    font-weight: 700;
    overflow-wrap: anywhere;
}


/* ============================================================
   PROFESSIONAL SECTION
   ============================================================ */

.c360-professional-layout {
    display: grid;
    grid-template-columns: 0.32fr 0.68fr;
    gap: 10px;
    padding: 0 20px 20px;
}

.c360-professional-item {
    min-height: 88px;
    padding: 16px;
    border-radius: 10px;
    background: #f8fafc;
    border: 1px solid #eaeef3;
}

.c360-professional-item-title {
    color: #65768a;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 0.9px;
    margin-bottom: 8px;
}

.c360-large-value {
    color: #172a33;
    font-size: 26px;
    font-weight: 900;
}

.c360-large-value span {
    color: #65768a;
    font-size: 11px;
    font-weight: 700;
}

.c360-expertise-text {
    color: #263b49;
    font-size: 13px;
    font-weight: 600;
    line-height: 1.55;
}


/* ============================================================
   PERFORMANCE SECTION  (mirrors .trainer-kpi-content)
   ============================================================ */

.c360-performance-row {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    padding: 0 20px 20px;
}

.c360-performance-item {
    min-height: 92px;
    padding: 14px 15px;
    border-radius: 10px;
    background: #f8fafc;
    border: 1px solid #eaeef3;
}

.c360-performance-label {
    color: #65768a;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 0.9px;
}

.c360-performance-value {
    margin-top: 6px;
    color: #172a33;
    font-size: 22px;
    font-weight: 900;
}

.c360-rating-value {
    color: #bd6b0b;
}

.c360-performance-note {
    margin-top: 3px;
    color: #7a8898;
    font-size: 10px;
}

.c360-performance-status {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-top: 7px;
    color: #158057;
    font-size: 15px;
    font-weight: 800;
}

.c360-status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #28a46f;
    box-shadow: 0 0 0 3px rgba(40, 164, 111, 0.12);
}


/* ============================================================
   ACCOUNT SECTION
   ============================================================ */

.c360-account-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    padding: 0 20px 20px;
}

.c360-account-field {
    min-height: 60px;
    padding: 12px 14px;
    border-radius: 10px;
    background: #f8fafc;
    border: 1px solid #eaeef3;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.c360-account-field span:first-child {
    color: #65768a;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 0.9px;
}

.c360-account-field strong {
    margin-top: 4px;
    color: #172a33;
    font-size: 13px;
    font-weight: 800;
    display: flex;
    align-items: center;
    gap: 7px;
}


/* ============================================================
   EXPERTISE TAGS  (mirrors .trainer-nav-count / KPI chip language)
   ============================================================ */

.c360-expertise-display {
    padding: 0 20px 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.c360-expertise-tag {
    min-height: 30px;
    padding: 0 13px;
    border-radius: 20px;
    background: #eee9ff;
    border: 1px solid #ded3ff;
    color: #673cff;
    font-size: 11px;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
}

.c360-no-expertise {
    color: #7b8597;
    font-size: 12px;
}


/* ============================================================
   EDIT MODE
   ============================================================ */

.c360-edit-section {
    padding: 0 20px 20px;
}

.c360-edit-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    margin-bottom: 12px;
}

.c360-edit-row:last-child {
    margin-bottom: 0;
}

.c360-edit-field {
    display: flex;
    flex-direction: column;
}

.c360-edit-field label {
    margin-bottom: 6px;
    color: #536476;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 0.6px;
}

.c360-edit-field input,
.c360-edit-field select {
    height: 40px;
    width: 100%;
    padding: 0 11px;
    border-radius: 8px;
    border: 1px solid #dfe6ee;
    background: #ffffff;
    color: #172a33;
    font-family: inherit;
    font-size: 12px;
    outline: none;
}

.c360-edit-field input:focus,
.c360-edit-field select:focus {
    border-color: #673cff;
    box-shadow: 0 0 0 3px rgba(103, 60, 255, 0.1);
}

.c360-edit-field input:disabled {
    background: #f4f7fb;
    color: #8b98a8;
    cursor: not-allowed;
}

.c360-edit-field small {
    margin-top: 5px;
    color: #7a8898;
    font-size: 10px;
}

.c360-input-suffix {
    position: relative;
}

.c360-input-suffix input {
    padding-right: 55px;
}

.c360-input-suffix span {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: #7a8898;
    font-size: 10px;
    font-weight: 700;
}


/* ============================================================
   EDIT ACTION BAR
   ============================================================ */

.c360-edit-actions {
    margin-bottom: 16px;
    padding: 14px 18px;
    border-radius: 15px;
    border: 1px solid #dfe6ee;
    background: #ffffff;
    box-shadow: 0 5px 16px rgba(31, 45, 61, 0.04);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
}

.c360-edit-message {
    display: flex;
    align-items: center;
    gap: 12px;
}

.c360-edit-message-icon {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: #eee9ff;
    color: #673cff;
    display: flex;
    align-items: center;
    justify-content: center;
}

.c360-edit-message strong {
    display: block;
    color: #172a33;
    font-size: 12px;
    font-weight: 800;
}

.c360-edit-message span {
    display: block;
    margin-top: 2px;
    color: #7a8898;
    font-size: 10px;
}

.c360-edit-buttons {
    display: flex;
    gap: 8px;
    flex-shrink: 0;
}

.c360-cancel-button {
    min-height: 36px;
    padding: 0 15px;
    border-radius: 9px;
    border: 1px solid #dfe6ee;
    background: #ffffff;
    color: #536476;
    font-size: 11px;
    font-weight: 800;
    cursor: pointer;
}

.c360-cancel-button:hover {
    background: #f4f7fb;
}

.c360-save-button {
    min-height: 36px;
    padding: 0 15px;
    border-radius: 9px;
    border: 1px solid #673cff;
    background: #673cff;
    color: #ffffff;
    font-size: 11px;
    font-weight: 800;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.c360-save-button:hover {
    background: #5730d8;
}

.c360-save-button:disabled,
.c360-cancel-button:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}


/* ============================================================
   BOTTOM ACTIONS
   ============================================================ */

.c360-bottom-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 4px 0 10px;
}


/* ============================================================
   LOADER
   ============================================================ */

.c360-loader {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    border: 3px solid #eee9ff;
    border-top-color: #673cff;
    animation: c360-profile-spin 0.75s linear infinite;
}

@keyframes c360-profile-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}


/* ============================================================
   TOAST
   ============================================================ */

.c360-toast {
    position: fixed;
    right: 24px;
    bottom: 22px;
    width: min(380px, calc(100vw - 30px));
    padding: 13px 15px;
    border-radius: 12px;
    background: #ffffff;
    border: 1px solid #dfe6ee;
    box-shadow: 0 14px 30px rgba(31, 45, 61, 0.14);
    display: flex;
    align-items: center;
    gap: 11px;
    z-index: 9999;
}

.c360-toast-icon {
    width: 32px;
    height: 32px;
    flex: 0 0 32px;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
}

.c360-success-toast .c360-toast-icon {
    background: #d9f2e5;
    color: #158057;
}

.c360-error-toast .c360-toast-icon {
    background: #ffe1e1;
    color: #bd303a;
}

.c360-toast > div:nth-child(2) {
    flex: 1;
}

.c360-toast strong {
    display: block;
    color: #172a33;
    font-size: 12px;
    font-weight: 800;
}

.c360-toast span {
    display: block;
    margin-top: 2px;
    color: #7a8898;
    font-size: 10px;
}

.c360-toast button {
    border: none;
    background: transparent;
    color: #8b98a8;
    font-size: 18px;
    cursor: pointer;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 900px) {
    .c360-profile-banner {
        flex-direction: column;
        align-items: flex-start;
    }

    .c360-id-card {
        width: 100%;
    }

    .c360-performance-row {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .c360-professional-layout {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 700px) {
    .c360-trainer-profile {
        padding: 20px 16px 40px;
    }

    .c360-profile-topbar {
        flex-wrap: wrap;
        gap: 12px;
    }

    .c360-information-row,
    .c360-account-row,
    .c360-edit-row {
        grid-template-columns: 1fr;
    }

    .c360-performance-row {
        grid-template-columns: 1fr 1fr;
    }

    .c360-edit-actions {
        flex-direction: column;
        align-items: flex-start;
    }

    .c360-edit-buttons {
        width: 100%;
    }

    .c360-edit-buttons button {
        flex: 1;
    }

    .c360-bottom-actions {
        flex-direction: column;
        gap: 8px;
        align-items: stretch;
    }
}

@media (max-width: 430px) {
    .c360-performance-row {
        grid-template-columns: 1fr;
    }
}

sp_widget.script:
(function() {

    /* ============================================================
       CAMPUS360 TRAINER PROFILE
       COMPLETE SERVER SCRIPT
       ============================================================ */


    var TABLE_NAME =
        'x_snc_campus360_trainer_master';


    /* ============================================================
       INITIAL RESPONSE
       ============================================================ */

    data.profileFound = false;

    data.profile = {};

    data.saveSuccess = false;

    data.saveError = '';

    data.profileError = '';

    data.requestedTrainerId = '';


    /* ============================================================
       TRAINER ID
       ============================================================ */

    function getTrainerId() {

        var trainerId = '';


        try {

            if (
                input &&
                input.profile &&
                input.profile.trainerId
            ) {

                trainerId =
                    String(
                        input.profile.trainerId
                    ).trim();

            }

        } catch (e) {}


        if (!trainerId) {

            try {

                trainerId =
                    $sp.getParameter(
                        'trainer'
                    ) || '';

            } catch (e2) {

                trainerId = '';

            }

        }


        return String(
            trainerId || ''
        ).trim();

    }


    /* ============================================================
       FIELD RESOLUTION
       ============================================================ */

    function findFieldName(
        gr,
        label,
        candidates
    ) {

        var i;

        var candidate;

        var element;


        /*
         * First check normal ServiceNow internal field names.
         */

        if (candidates) {

            for (
                i = 0;
                i < candidates.length;
                i++
            ) {

                candidate =
                    candidates[i];


                try {

                    element =
                        gr.getElement(
                            candidate
                        );


                    if (element) {

                        return candidate;

                    }

                } catch (candidateError) {}

            }

        }


        /*
         * Then inspect the table fields by label.
         */

        try {

            var elements =
                gr.getElements();


            if (
                elements &&
                typeof elements.length !== 'undefined'
            ) {

                for (
                    i = 0;
                    i < elements.length;
                    i++
                ) {

                    try {

                        element =
                            elements[i];


                        if (!element) {

                            continue;

                        }


                        var currentLabel =
                            String(
                                element.getLabel() || ''
                            )
                            .trim()
                            .toLowerCase();


                        if (
                            currentLabel ===
                            String(
                                label
                            )
                            .trim()
                            .toLowerCase()
                        ) {

                            return String(
                                element.getName()
                            );

                        }

                    } catch (elementError) {}

                }

            }

        } catch (elementsError) {}


        /*
         * Finally check sys_dictionary.
         */

        try {

            var dictionary =
                new GlideRecord(
                    'sys_dictionary'
                );


            dictionary.addQuery(
                'name',
                TABLE_NAME
            );


            dictionary.addQuery(
                'column_label',
                label
            );


            dictionary.setLimit(1);

            dictionary.query();


            if (
                dictionary.next()
            ) {

                return String(
                    dictionary.getValue(
                        'element'
                    )
                );

            }

        } catch (dictionaryError) {}


        return '';

    }


    /* ============================================================
       FIELD MAP
       ============================================================ */

    function getFieldMap(gr) {

        var map = {};


        map.trainerId =
            findFieldName(
                gr,
                'Trainer ID',
                [
                    'trainer_id',
                    'u_trainer_id'
                ]
            );


        map.trainerName =
            findFieldName(
                gr,
                'Trainer Name',
                [
                    'trainer_name',
                    'u_trainer_name'
                ]
            );


        map.experience =
            findFieldName(
                gr,
                'Experience',
                [
                    'experience',
                    'u_experience'
                ]
            );


        map.expertise =
            findFieldName(
                gr,
                'Expertise',
                [
                    'expertise',
                    'u_expertise'
                ]
            );


        map.email =
            findFieldName(
                gr,
                'Email',
                [
                    'email',
                    'u_email'
                ]
            );


        map.phone =
            findFieldName(
                gr,
                'Phone Number',
                [
                    'phone_number',
                    'u_phone_number',
                    'phone'
                ]
            );


        map.rating =
            findFieldName(
                gr,
                'Rating',
                [
                    'rating',
                    'u_rating'
                ]
            );


        map.totalInterviews =
            findFieldName(
                gr,
                'Total Interviews',
                [
                    'total_interviews',
                    'u_total_interviews'
                ]
            );


        map.status =
            findFieldName(
                gr,
                'Status',
                [
                    'status',
                    'u_status'
                ]
            );


        return map;

    }


    /* ============================================================
       SAFE GET VALUE
       ============================================================ */

    function getValue(
        gr,
        fieldName
    ) {

        if (!fieldName) {

            return '';

        }


        try {

            return String(
                gr.getValue(
                    fieldName
                ) || ''
            );

        } catch (e) {

            return '';

        }

    }


    /* ============================================================
       SAFE DISPLAY VALUE
       ============================================================ */

    function getDisplayValue(
        gr,
        fieldName
    ) {

        if (!fieldName) {

            return '';

        }


        try {

            return String(
                gr.getDisplayValue(
                    fieldName
                ) || ''
            );

        } catch (e) {

            return '';

        }

    }


    /* ============================================================
       PARSE NUMBER
       ============================================================ */

    function parseNumber(value) {

        if (
            value === null ||
            value === undefined ||
            value === ''
        ) {

            return '';

        }


        var number =
            parseFloat(
                value
            );


        if (isNaN(number)) {

            return '';

        }


        return number;

    }


    /* ============================================================
       PARSE INTEGER
       ============================================================ */

    function parseInteger(value) {

        if (
            value === null ||
            value === undefined ||
            value === ''
        ) {

            return 0;

        }


        var number =
            parseInt(
                value,
                10
            );


        if (isNaN(number)) {

            return 0;

        }


        return number;

    }


    /* ============================================================
       INITIALS
       ============================================================ */

    function getInitials(name) {

        name =
            String(
                name || ''
            ).trim();


        if (!name) {

            return 'TR';

        }


        var parts =
            name.split(
                /\s+/
            );


        if (
            parts.length === 1
        ) {

            return parts[0]
                .substring(
                    0,
                    2
                )
                .toUpperCase();

        }


        return (
            parts[0].charAt(0) +
            parts[
                parts.length - 1
            ].charAt(0)
        ).toUpperCase();

    }


    /* ============================================================
       EXPERTISE LIST
       ============================================================ */

    function buildExpertiseList(
        expertise
    ) {

        expertise =
            String(
                expertise || ''
            ).trim();


        if (!expertise) {

            return [];

        }


        var values =
            expertise.split(
                /[,;|]+/
            );


        var result = [];


        for (
            var i = 0;
            i < values.length;
            i++
        ) {

            var item =
                String(
                    values[i] || ''
                ).trim();


            if (item) {

                result.push(
                    item
                );

            }

        }


        return result;

    }


    /* ============================================================
       BUILD PROFILE
       ============================================================ */

    function buildProfile(
        gr,
        fieldMap
    ) {

        var trainerId =
            getValue(
                gr,
                fieldMap.trainerId
            );


        var trainerName =
            getValue(
                gr,
                fieldMap.trainerName
            );


        var experience =
            parseNumber(
                getValue(
                    gr,
                    fieldMap.experience
                )
            );


        var expertise =
            getValue(
                gr,
                fieldMap.expertise
            );


        var email =
            getValue(
                gr,
                fieldMap.email
            );


        var phone =
            getValue(
                gr,
                fieldMap.phone
            );


        var rating =
            parseNumber(
                getValue(
                    gr,
                    fieldMap.rating
                )
            );


        var totalInterviews =
            parseInteger(
                getValue(
                    gr,
                    fieldMap.totalInterviews
                )
            );


        var status =
            getDisplayValue(
                gr,
                fieldMap.status
            );


        if (!status) {

            status =
                getValue(
                    gr,
                    fieldMap.status
                );

        }


        if (!status) {

            status =
                'Active';

        }


        var ratingDisplay =
            rating === '' ?
            'Not Rated' :
            Number(
                rating
            ).toFixed(1);


        return {

            sysId:
                String(
                    gr.getUniqueValue()
                ),

            trainerId:
                trainerId,

            trainerName:
                trainerName,

            experience:
                experience,

            expertise:
                expertise,

            expertiseList:
                buildExpertiseList(
                    expertise
                ),

            email:
                email,

            phone:
                phone,

            rating:
                rating,

            ratingDisplay:
                ratingDisplay,

            totalInterviews:
                totalInterviews,

            status:
                status,

            initials:
                getInitials(
                    trainerName
                )

        };

    }


    /* ============================================================
       LOAD PROFILE
       ============================================================ */

    function loadProfile(
        trainerId
    ) {

        data.profileFound =
            false;

        data.profile =
            {};

        data.requestedTrainerId =
            trainerId;


        if (!trainerId) {

            data.profileError =
                'Trainer ID was not supplied in the URL.';

            return;

        }


        var gr =
            new GlideRecord(
                TABLE_NAME
            );


        var fieldMap =
            getFieldMap(
                gr
            );


        if (!fieldMap.trainerId) {

            data.profileError =
                'Trainer ID field was not found in Trainer Master.';

            return;

        }


        gr.addQuery(
            fieldMap.trainerId,
            trainerId
        );


        gr.setLimit(1);

        gr.query();


        if (!gr.next()) {

            data.profileFound =
                false;

            return;

        }


        data.profileFound =
            true;


        data.profile =
            buildProfile(
                gr,
                fieldMap
            );

    }


    /* ============================================================
       SAVE PROFILE
       ============================================================ */

    function saveProfile(
        submitted
    ) {

        data.saveSuccess =
            false;

        data.saveError =
            '';


        if (
            !submitted ||
            !submitted.trainerId
        ) {

            data.saveError =
                'Trainer ID is required.';

            return;

        }


        var trainerId =
            String(
                submitted.trainerId
            ).trim();


        var gr =
            new GlideRecord(
                TABLE_NAME
            );


        var fieldMap =
            getFieldMap(
                gr
            );


        if (!fieldMap.trainerId) {

            data.saveError =
                'Trainer ID field could not be resolved.';

            return;

        }


        gr.addQuery(
            fieldMap.trainerId,
            trainerId
        );


        gr.setLimit(1);

        gr.query();


        if (!gr.next()) {

            data.saveError =
                'Trainer Master record was not found for ' +
                trainerId +
                '.';

            return;

        }


        /* ========================================================
           TRAINER NAME
           ======================================================== */

        if (
            fieldMap.trainerName &&
            submitted.trainerName !== undefined
        ) {

            var trainerName =
                String(
                    submitted.trainerName || ''
                ).trim();


            if (!trainerName) {

                data.saveError =
                    'Trainer Name is required.';

                return;

            }


            gr.setValue(
                fieldMap.trainerName,
                trainerName
            );

        }


        /* ========================================================
           EXPERIENCE
           ======================================================== */

        if (
            fieldMap.experience &&
            submitted.experience !== undefined
        ) {

            if (
                submitted.experience === '' ||
                submitted.experience === null
            ) {

                gr.setValue(
                    fieldMap.experience,
                    ''
                );

            } else {

                var experience =
                    parseInt(
                        submitted.experience,
                        10
                    );


                if (
                    isNaN(experience) ||
                    experience < 0
                ) {

                    data.saveError =
                        'Experience must be zero or greater.';

                    return;

                }


                gr.setValue(
                    fieldMap.experience,
                    experience
                );

            }

        }


        /* ========================================================
           EXPERTISE
           ======================================================== */

        if (
            fieldMap.expertise &&
            submitted.expertise !== undefined
        ) {

            gr.setValue(
                fieldMap.expertise,
                String(
                    submitted.expertise || ''
                ).trim()
            );

        }


        /* ========================================================
           EMAIL
           ======================================================== */

        if (
            fieldMap.email &&
            submitted.email !== undefined
        ) {

            gr.setValue(
                fieldMap.email,
                String(
                    submitted.email || ''
                ).trim()
            );

        }


        /* ========================================================
           PHONE
           ======================================================== */

        if (
            fieldMap.phone &&
            submitted.phone !== undefined
        ) {

            gr.setValue(
                fieldMap.phone,
                String(
                    submitted.phone || ''
                ).trim()
            );

        }


        /* ========================================================
           RATING
           ======================================================== */

        if (
            fieldMap.rating &&
            submitted.rating !== undefined
        ) {

            if (
                submitted.rating === '' ||
                submitted.rating === null
            ) {

                gr.setValue(
                    fieldMap.rating,
                    ''
                );

            } else {

                var rating =
                    parseFloat(
                        submitted.rating
                    );


                if (
                    isNaN(rating) ||
                    rating < 0 ||
                    rating > 5
                ) {

                    data.saveError =
                        'Rating must be between 0 and 5.';

                    return;

                }


                gr.setValue(
                    fieldMap.rating,
                    rating
                );

            }

        }


        /* ========================================================
           TOTAL INTERVIEWS
           ======================================================== */

        if (
            fieldMap.totalInterviews &&
            submitted.totalInterviews !== undefined
        ) {

            var totalInterviews =
                parseInt(
                    submitted.totalInterviews,
                    10
                );


            if (
                isNaN(totalInterviews) ||
                totalInterviews < 0
            ) {

                data.saveError =
                    'Total Interviews must be zero or greater.';

                return;

            }


            gr.setValue(
                fieldMap.totalInterviews,
                totalInterviews
            );

        }


        /* ========================================================
           STATUS
           ======================================================== */

        if (
            fieldMap.status &&
            submitted.status !== undefined
        ) {

            var status =
                String(
                    submitted.status || ''
                ).trim();


            if (status) {

                gr.setValue(
                    fieldMap.status,
                    status
                );

            }

        }


        /* ========================================================
           UPDATE RECORD
           ======================================================== */

        try {

            gr.update();

        } catch (updateError) {

            data.saveError =
                'The Trainer Master record could not be updated.';

            return;

        }


        /* ========================================================
           RELOAD
           ======================================================== */

        var updated =
            new GlideRecord(
                TABLE_NAME
            );


        updated.addQuery(
            fieldMap.trainerId,
            trainerId
        );


        updated.setLimit(1);

        updated.query();


        if (
            updated.next()
        ) {

            data.profileFound =
                true;

            data.profile =
                buildProfile(
                    updated,
                    fieldMap
                );

        }


        data.saveSuccess =
            true;

    }


    /* ============================================================
       MAIN
       ============================================================ */

    var trainerId =
        getTrainerId();


    data.requestedTrainerId =
        trainerId;


    if (
        input &&
        input.action ===
        'saveProfile'
    ) {

        saveProfile(
            input.profile
        );

    } else {

        loadProfile(
            trainerId
        );

    }

})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
